import tempfile,unittest,json,pathlib,subprocess
ROOT=pathlib.Path(__file__).parents[1]
class BasicSkillTest(unittest.TestCase):
 def test_rest_learns_basic_once_per_server_ack_before_sitting(self):
  with tempfile.TemporaryDirectory() as d:
   code="BEGIN{\npackage Globals;use Exporter 'import';our @EXPORT=qw($char $charID $accountID $field $net $messageSender %config);our($char,$charID,$accountID,$field,$net,$messageSender);our%config;$INC{'Globals.pm'}=1;\npackage Plugins;sub register{}sub addHooks{return 1}sub delHooks{};$INC{'Plugins.pm'}=1;\npackage Utils;use Exporter 'import';our @EXPORT_OK=qw(calcPosition);sub calcPosition{{x=>20,y=>25}};$INC{'Utils.pm'}=1;\npackage Network;sub IN_GAME(){5};$INC{'Network.pm'}=1;\npackage AI;sub clear{}sub action{''};$INC{'AI.pm'}=1;\npackage FakeChar;sub sendSit{$_[0]{sitting}=1}sub sendStand{$_[0]{sitting}=0}\npackage FakeSender;sub sendAddSkillPoint{push@{$_[0]{learn}},$_[1]}sub sendRestart{$_[0]{restart}=$_[1]+1}\n}\nrequire $ARGV[0];$ENV{RESIDENT_RUN_DIR}=$ARGV[1];$ENV{RESIDENT_ESTOP}=$ARGV[1].'/ESTOP';$Globals::char=bless{hp=>10,hp_max=>40,weight=>0,weight_max=>1000,skills=>{NV_BASIC=>{lv=>0}},points_skill=>5,pos_to=>{x=>20,y=>25}},'FakeChar';$Globals::field={baseName=>'prontera'};$Globals::messageSender=bless{},'FakeSender';\nmy@frames;{no warnings 'redefine';*residentBody::emit=sub{push@frames,[@_]};}\nmy$ep=residentBody::telemetryFrame()->{body_epoch};my$m={proto=>1,type=>'skill_start',action_id=>'rest',idem_key=>'rest',expect_epoch=>$ep,skill=>'rest',params=>{hp_pct=>80},deadline_ts=>Time::HiRes::time()+60};residentBody::command($m);residentBody::pollSkill();my$count_before=scalar@{$Globals::messageSender->{learn}//[]};my$sat_before=$Globals::char->{sitting}//0;residentBody::pollSkill();my$count_duplicate=scalar@{$Globals::messageSender->{learn}//[]};for my$lv(1..3){$Globals::char->{skills}{NV_BASIC}{lv}=$lv;$Globals::char->{points_skill}=5-$lv;residentBody::pollSkill()}my$sat_after=$Globals::char->{sitting}//0;print JSON::PP::encode_json({before=>$count_before,duplicate=>$count_duplicate,ids=>$Globals::messageSender->{learn}//[],sat_before=>$sat_before,sat_after=>$sat_after});"
   p=subprocess.run(['perl','-e',code,str(ROOT/'plugins/residentBody/residentBody.pl'),d],capture_output=True,text=True)
   self.assertEqual(p.returncode,0,p.stderr);r=json.loads(p.stdout);self.assertEqual(r['sat_before'],0);self.assertEqual(r['before'],1);self.assertEqual(r['duplicate'],1);self.assertEqual(r['ids'],[1,1,1]);self.assertEqual(r['sat_after'],1)
